impl MortarClass {
    /// 🗜️ Characteristic compressive strength f_m [MPa] of the mortar class.
    pub fn f_m_mpa(self) -> f64 {
        match self {
            Self::M1 => 1.0,
            Self::M2_5 => 2.5,
            Self::M5 => 5.0,
            Self::M10 => 10.0,
            Self::M15 => 15.0,
            Self::M20 => 20.0,
